// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

// Module-level font loading for Lambda compatibility
const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type HaloSpheresProps = Record<string, any>;

const HaloSpheres: React.FC<HaloSpheresProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  arcColor = "#ffffff",
  orbPrimaryColor = "#2a6fdb",
  orbSecondaryColor = "#a2d2ff",
  orbGlowColor = "#2a6fdb",
  textColor = "#ffffff",
  fontSize = 46.1,
  items = ["TRUST ME", "TRY", "BUY NOW", "EXPENSIVE", "CHEAP"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Core layout metrics (optimized for 16:9, adaptable)
  const cx = width / 2;
  const cy = height * 0.42;
  const R = width * 0.38;

  // Drawing sequence metrics
  const arcFanStartFrame = 15;
  const arcFanDuration = 45;
  
  // Progress of the arc fanning out from the center (0 to 1)
  const arcFanProgress = interpolate(
    frame,
    [arcFanStartFrame, arcFanStartFrame + arcFanDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const tiltRad = 0;
  const spin = 0;

  // Ellipse radii based on 3D tilt projection
  const rx = R;
  const ry = Math.max(1, R * Math.cos(tiltRad));

  // Arc boundaries (from Right to Left over the top)
  const arcStartBase = -20;
  const arcEndBase = 200;
  
  // Calculate projected SVG path coordinates for the arc
  const startRad = (arcStartBase + spin) * (Math.PI / 180);
  const endRad = (arcEndBase + spin) * (Math.PI / 180);

  const sx = cx + rx * Math.cos(startRad);
  const sy = cy - ry * Math.sin(startRad);
  const ex = cx + rx * Math.cos(endRad);
  const ey = cy - ry * Math.sin(endRad);

  const pathData = `M ${sx} ${sy} A ${rx} ${ry} 0 1 0 ${ex} ${ey}`;

  // Angles for exact placement of the 5 orbs (visually Left to Right)
  const orbAngles = [200, 145, 90, 35, -20];
  const orbSize = width * 0.15;
  
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // After the arc fans out completely, we wait a moment before revealing orbs
  const revealSequenceStart = arcFanStartFrame + arcFanDuration + 5;
  const revealStagger = 12;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* 2D Projected Arc Line - Fanning Out From Center */}
      <svg style={{ position: "absolute", width: "100%", height: "100%", overflow: "visible" }}>
        <path
          d={pathData}
          fill="none"
          stroke={arcColor}
          strokeWidth={3}
          pathLength={100}
          // The math here perfectly draws the path outward from its exact midpoint (50)
          strokeDasharray={`${arcFanProgress * 100} 100`}
          strokeDashoffset={arcFanProgress * 50 - 50}
          style={{
            filter: "drop-shadow(0px 0px 4px rgba(255,255,255,0.5))"
          }}
        />
      </svg>

      {/* Orbs Sequence */}
      {items.slice(0, 5).map((text, i) => {
        const baseTheta = orbAngles[i];
        const currentTheta = baseTheta + spin;
        const rad = currentTheta * (Math.PI / 180);
        
        const x = cx + rx * Math.cos(rad);
        const y = cy - ry * Math.sin(rad);

        // Calculate distance from center (90 degrees) to sync pop-in with fanning arc
        const centerAngle = 90;
        const maxDistance = 110; // Math.abs(200 - 90)
        const distanceFromCenter = Math.abs(baseTheta - centerAngle);
        const normalizedDistance = distanceFromCenter / maxDistance;
        
        // Pop in the blurred orb right as the fanning arc reaches its position
        const popInDelay = arcFanStartFrame + normalizedDistance * arcFanDuration;

        const orbScale = spring({
          frame: frame - popInDelay,
          fps,
          config: { damping: 12, mass: 0.8, stiffness: 120 },
        });

        // Unblur (reveal) one by one AFTER the arc has fully fanned out
        const unblurDelay = revealSequenceStart + i * revealStagger;
        const unblurProgress = spring({
          frame: frame - unblurDelay,
          fps,
          config: { damping: 14, mass: 0.8, stiffness: 90 },
        });

        // Interpolate from heavily blurred to clear
        const orbBlur = interpolate(unblurProgress, [0, 1], [25, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });

        const glowIntensity = interpolate(orbScale, [0, 1], [0, 0.8], { extrapolateRight: "clamp" });

        return (
          <div
            key={`orb-${i}`}
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              width: orbSize,
              height: orbSize,
              borderRadius: "50%",
              transform: `translate(${x - orbSize / 2}px, ${y - orbSize / 2}px) scale(${orbScale})`,
              background: `radial-gradient(circle at 30% 30%, #ffffff 0%, ${orbSecondaryColor} 20%, ${orbPrimaryColor} 60%, #03045e 100%)`,
              boxShadow: `
                0 0 ${orbSize * 0.2}px rgba(42, 111, 219, ${glowIntensity}), 
                inset -${orbSize * 0.1}px -${orbSize * 0.1}px ${orbSize * 0.2}px rgba(0,0,0,0.6), 
                inset ${orbSize * 0.08}px ${orbSize * 0.08}px ${orbSize * 0.15}px rgba(255,255,255,0.8)
              `,
              border: "1px solid rgba(255, 255, 255, 0.4)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              padding: orbSize * 0.1,
              boxSizing: "border-box",
              opacity: orbScale > 0.01 ? 1 : 0,
              filter: `blur(${orbBlur}px)`,
              transition: "none",
            }}
          >
            <span
              style={{
                fontFamily: spaceGrotesk,
                fontWeight: 800,
                // Scales proportionally with orbSize while exposing an intuitive size control
                fontSize: orbSize * (fontSize / 288),
                color: textColor,
                textAlign: "center",
                lineHeight: 1.05,
                textTransform: "uppercase",
                textShadow: `0px 3px 8px rgba(0,0,0,0.8), 0px 0px 10px ${orbGlowColor}`,
                wordBreak: "break-word",
                transition: "none",
              }}
            >
              {text}
            </span>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default HaloSpheres;